import numpy as np, wfdb, scipy.signal as ss, json, sys, os
FS=500
def load(e):
    r=wfdb.rdrecord(f'ecg/{e}')
    x=np.nan_to_num(r.p_signal.astype(float))
    return x, r.sig_name
def bp(x, lo=0.5, hi=40):
    b,a=ss.butter(3,[lo/(FS/2),hi/(FS/2)],'band')
    return ss.filtfilt(b,a,x,axis=0)
def notch(x):
    b,a=ss.iirnotch(60,30,FS); return ss.filtfilt(b,a,x,axis=0)
def rpeaks(sig):
    import neurokit2 as nk
    _,info=nk.ecg_peaks(sig, sampling_rate=FS, correct_artifacts=True)
    return np.array(info['ECG_R_Peaks'])
def analyze(e):
    raw,names=load(e)
    x=notch(bp(raw))
    idx={n:i for i,n in enumerate(names)}
    # composite for detection
    comp=np.sqrt((np.diff(x,axis=0)**2).sum(axis=1))
    lead2=x[:,idx['II']]
    try:
        R=rpeaks(lead2)
    except Exception:
        R=np.array([])
    if len(R)<3:
        R=rpeaks(x[:,idx['V2']])
    return dict(e=e,x=x,idx=idx,R=R,comp=comp,raw=raw,names=names)
